// s5_expr.js - Expression evaluator with + - * / precedence and error handling

function evaluate(expr, vars = {}) {
    // Remove all spaces
    expr = expr.replace(/\s/g, '');

    // Check for empty expression
    if (expr === '') {
        throw new Error('Empty expression');
    }

    // Check for invalid characters (allowing letters for variable names)
    if (!/^[0-9+\-*/.()^a-zA-Z_]+$/.test(expr)) {
        throw new Error('Invalid characters in expression');
    }

    // Parse and evaluate the expression
    function parseExpression() {
        let result = parseTerm();

        while (true) {
            const char = expr[pos];
            if (char === '+') {
                pos++;
                result += parseTerm();
            } else if (char === '-') {
                pos++;
                result -= parseTerm();
            } else {
                break;
            }
        }

        return result;
    }

    function parsePower() {
        let result = parseFactor();

        // Handle right-associative power operations
        if (expr[pos] === '^') {
            pos++;
            const exponent = parsePower();  // Right-associative: 2^3^2 = 2^(3^2) = 2^9 = 512
            result = Math.pow(result, exponent);
        }

        return result;
    }

    function parseTerm() {
        let result = parsePower();

        while (true) {
            const char = expr[pos];
            if (char === '*') {
                pos++;
                result *= parsePower();
            } else if (char === '/') {
                pos++;
                const divisor = parsePower();
                if (divisor === 0) {
                    throw new Error('Division by zero');
                }
                result /= divisor;
            } else {
                break;
            }
        }

        return result;
    }

    function parseFactor() {
        if (expr[pos] === '(') {
            pos++;
            const result = parseExpression();
            if (expr[pos] !== ')') {
                throw new Error('Missing closing parenthesis');
            }
            pos++;
            return result;
        } else if (expr[pos] === '-') {
            pos++;
            // For unary minus, we need to handle it properly with precedence
            // The unary minus should apply to the next factor, but we need to make sure
            // it's not applied to a factor that's already been processed
            return -parsePower();  // Apply unary minus to the power result
        } else if (/[a-zA-Z_]/.test(expr[pos])) {
            // Handle function calls
            let start = pos;
            while (pos < expr.length && /[a-zA-Z0-9_]/.test(expr[pos])) {
                pos++;
            }
            const funcName = expr.substring(start, pos);

            // Check for opening parenthesis
            if (expr[pos] !== '(') {
                throw new Error(`Function ${funcName} must be followed by parentheses`);
            }
            pos++; // Skip the '('

            // Parse arguments
            const args = [];
            if (expr[pos] !== ')') { // If not empty parentheses
                while (true) {
                    args.push(parseExpression());
                    if (expr[pos] === ',') {
                        pos++; // Skip the comma
                    } else if (expr[pos] === ')') {
                        break;
                    } else {
                        throw new Error('Expected comma or closing parenthesis');
                    }
                }
            } else {
                // Empty parentheses - no arguments
            }

            if (expr[pos] !== ')') {
                throw new Error('Missing closing parenthesis');
            }
            pos++; // Skip the ')'

            // Apply the function
            switch (funcName) {
                case 'min':
                    if (args.length === 0) {
                        throw new Error('min() requires at least one argument');
                    }
                    return Math.min(...args);
                case 'max':
                    if (args.length === 0) {
                        throw new Error('max() requires at least one argument');
                    }
                    return Math.max(...args);
                case 'abs':
                    if (args.length !== 1) {
                        throw new Error('abs() requires exactly one argument');
                    }
                    return Math.abs(args[0]);
                case 'sqrt':
                    if (args.length !== 1) {
                        throw new Error('sqrt() requires exactly one argument');
                    }
                    if (args[0] < 0) {
                        throw new Error('sqrt() of negative number');
                    }
                    return Math.sqrt(args[0]);
                default:
                    throw new Error(`Unknown function: ${funcName}`);
            }
        } else {
            return parseNumber();
        }
    }

    function parseNumber() {
        let start = pos;

        // Handle variable names (letters and underscores, followed by letters, digits, or underscores)
        if (/[a-zA-Z_]/.test(expr[pos])) {
            while (pos < expr.length && /[a-zA-Z0-9_]/.test(expr[pos])) {
                pos++;
            }

            const varName = expr.substring(start, pos);

            if (vars.hasOwnProperty(varName)) {
                return vars[varName];
            } else {
                throw new Error(`Unknown variable: ${varName}`);
            }
        }
        // Handle decimal numbers
        else if (/\d/.test(expr[pos])) {
            while (pos < expr.length && (/\d/.test(expr[pos]) || expr[pos] === '.')) {
                pos++;
            }

            if (start === pos) {
                throw new Error('Invalid number');
            }

            const numStr = expr.substring(start, pos);
            const num = parseFloat(numStr);

            if (isNaN(num)) {
                throw new Error('Invalid number');
            }

            return num;
        }
        else {
            throw new Error('Invalid number');
        }
    }

    let pos = 0;
    const result = parseExpression();

    // Check if we consumed the entire expression
    if (pos < expr.length) {
        throw new Error('Invalid expression');
    }

    return result;
}

// Asserts to test the evaluate function
function runAsserts() {
    // Test basic operations
    console.assert(evaluate("2 + 3") === 5, "2 + 3 should equal 5");
    console.assert(evaluate("10 - 4") === 6, "10 - 4 should equal 6");
    console.assert(evaluate("3 * 7") === 21, "3 * 7 should equal 21");
    console.assert(evaluate("15 / 3") === 5, "15 / 3 should equal 5");

    // Test precedence
    console.assert(evaluate("2 + 3 * 4") === 14, "2 + 3 * 4 should equal 14 (multiplication first)");
    console.assert(evaluate("10 - 6 / 2") === 7, "10 - 6 / 2 should equal 7 (division first)");
    console.assert(evaluate("2 * 3 + 4") === 10, "2 * 3 + 4 should equal 10 (multiplication first)");

    // Test left-to-right evaluation for same precedence
    console.assert(evaluate("10 - 4 - 2") === 4, "10 - 4 - 2 should equal 4 (left to right)");
    console.assert(evaluate("12 / 4 / 3") === 1, "12 / 4 / 3 should equal 1 (left to right)");

    // Test decimals
    console.assert(evaluate("2.5 + 1.5") === 4, "2.5 + 1.5 should equal 4");
    console.assert(evaluate("7.5 / 2.5") === 3, "7.5 / 2.5 should equal 3");

    // Test parentheses
    console.assert(evaluate("(2 + 3) * 4") === 20, "(2 + 3) * 4 should equal 20");
    console.assert(evaluate("2 * (3 + 4)") === 14, "2 * (3 + 4) should equal 14");

    // Test negative numbers
    console.assert(evaluate("-5 + 3") === -2, "-5 + 3 should equal -2");
    console.assert(evaluate("5 + -3") === 2, "5 + -3 should equal 2");

    // Test power operator
    console.assert(evaluate("2^3") === 8, "2^3 should equal 8");
    console.assert(evaluate("2^3^2") === 512, "2^3^2 should equal 512 (right associative)");
    console.assert(evaluate("-2^2") === -4, "-2^2 should equal -4 (negative applies after power)");

    // Test new functions
    console.assert(evaluate("min(1, 2, 3)") === 1, "min(1, 2, 3) should equal 1");
    console.assert(evaluate("max(1, 2, 3)") === 3, "max(1, 2, 3) should equal 3");
    console.assert(evaluate("abs(-5)") === 5, "abs(-5) should equal 5");
    console.assert(evaluate("sqrt(9)") === 3, "sqrt(9) should equal 3");

    console.log("All asserts passed!");
}

// Run the tests
runAsserts();

// Export the evaluate function
module.exports = { evaluate };

